const isMarker=n=>!!n&&['start','end'].includes(n.kind);
function markerGraphic(kind){return kind==='start'?'<svg viewBox="0 0 32 32" aria-hidden="true"><path d="M8 28V4M9 5h17l-5 6 5 6H9" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linejoin="round"/></svg>':'<svg viewBox="0 0 32 32" aria-hidden="true"><rect x="7" y="7" width="18" height="18" rx="2" fill="currentColor"/></svg>';}
