function connectPath(){const p=path();for(let i=1;i<p.length;i++)if(!edge(p[i-1],p[i]))board.edges.push({id:uid(),from:p[i-1],to:p[i],transition:'cut',notes:''});board.render_path_ends_here=true;}
function bindNodeFields(box,id){
  box.querySelectorAll('[data-field]').forEach(el=>{
    let checkpointed=false;el.onfocus=()=>{checkpointed=false;};
    const apply=()=>{const current=node(id);if(!current)return;const value=el.type==='number'?Number(el.value):el.value;if(current[el.dataset.field]===value)return;
      if(!checkpointed){checkpoint();checkpointed=true;}current[el.dataset.field]=value;changed(false);refreshNodeText(current);renderEdges();};
    el.oninput=apply;el.onchange=apply;
  });
}
function field(name,label,value,type='text'){return `<label for="field-${name}">${label}</label>${type==='textarea'?`<textarea id="field-${name}" data-field="${name}">${escapeHTML(value)}</textarea>`:`<input id="field-${name}" data-field="${name}" type="${type}" ${type==='number'?'min="0" step="0.1"':''} value="${escapeHTML(value)}">`}`;}
let popoverPosition=null,popoverScene=null,popoverPinned=false;
