function previewAuxiliaryConnection(event){const card=auxiliaryCard(drag.id),type=drag.sourceScene?drag.auxiliaryType:auxiliaryType(card),rect=$('viewport').getBoundingClientRect();if(!card&&!drag.sourceScene)return;let line=$('auxiliary-preview');if(!line){line=document.createElementNS('http://www.w3.org/2000/svg','path');line.id='auxiliary-preview';$('connections').append(line);}line.setAttribute('class','auxiliary-wire '+type);const point={x:(event.clientX-rect.left-pan.x)/zoom,y:(event.clientY-rect.top-pan.y)/zoom};if(drag.sourceScene){const start=auxiliarySocket({kind:type==='feedback'?'feedback':'effect'},drag.sourceScene);line.setAttribute('d',`M ${start.x} ${start.y} C ${start.x} ${start.y+40}, ${point.x} ${point.y-40}, ${point.x} ${point.y}`);}else if(drag.auxiliaryTarget&&drag.auxiliaryEndpoint==='card'){const destination=auxiliarySocket(card,drag.auxiliaryTarget);line.setAttribute('d',`M ${point.x} ${point.y} C ${point.x} ${point.y+40}, ${destination.x} ${destination.y-40}, ${destination.x} ${destination.y}`);}else line.setAttribute('d',auxiliaryCable(card,null,point));clearAuxiliaryDropTargets();const hit=document.elementFromPoint?.(event.clientX,event.clientY),candidate=drag.sourceScene?hit?.closest('[data-effect]'):hit?.closest('[data-node]')||hit?.closest('[data-effect]');if(candidate){const aux=candidate.dataset.effect?auxiliaryCard(candidate.dataset.effect):null;if(!aux||auxiliaryType(aux)===type)candidate.classList.add('auxiliary-drop-target');}}

function placeNewEffectCard(id){const effect=board.effects.find(e=>e.id===id),parent=node(effect?.parent_node_id);if(!effect||!parent)return;const siblings=board.effects.filter(e=>e.id!==id&&auxiliaryTargets(e).includes(parent.id)),top=Math.min(Number(parent.y)||0,...siblings.map(e=>Number(e.y)||0)),height=Math.max(260,effectCardHeight(id));effect.y=top-height-24;renderEffects();renderEdges();changed(false);}
async function addEffectAtSocket(parentId){const owner=board.board_id;try{if(!effectRegistry.some(e=>e.presets?.length)){const result=await api('/api/effects');effectRegistry=result.effects||[];}if(board.board_id!==owner||!node(parentId)||reviewMode)return;const kind=effectRegistry.find(e=>e.presets?.length);if(!kind){status('No effect presets are available for this project.',true);return;}const preset=kind.presets[0];let id;commit(()=>{const parent=node(parentId),siblings=board.effects.filter(e=>auxiliaryTargets(e).includes(parentId)),effect={id:uid(),parent_node_id:parentId,target_node_ids:[parentId],kind:kind.id,preset_id:preset.id,enabled:true,settings:{...(preset.settings||{}),intensity:preset.settings?.intensity??1},x:(parent.x||0)+16,y:(parent.y||0)-100-siblings.length*100,follow_parent:true};id=effect.id;board.effects.push(effect);selectedIds.clear();selectedEffectIds=new Set([id]);selection={type:'effect',id};});placeNewEffectCard(id);showEffectInViewport(id);document.querySelector(`[data-effect="${CSS.escape(id)}"] [data-card-preset]`)?.focus();}catch(e){status('Effect creation failed: '+e.message,true);}}
