function shiftEffects(previous){for(const e of auxiliaryCards()){const before=previous.get(e.parent_node_id),parent=node(e.parent_node_id);if(before&&parent&&e.follow_parent!==false){e.x=(e.x||0)+parent.x-before.x;e.y=(e.y||0)+parent.y-before.y;}}}
function showEffectInViewport(id){
  const card=document.getElementById('effect-'+targetId(id));if(!card)return;
  const rect=card.getBoundingClientRect(),bounds=$('viewport').getBoundingClientRect(),margin=16;
  if(rect.left<bounds.left+margin)pan.x+=bounds.left+margin-rect.left;else if(rect.right>bounds.right-margin)pan.x-=rect.right-(bounds.right-margin);
  if(rect.top<bounds.top+margin)pan.y+=bounds.top+margin-rect.top;else if(rect.bottom>bounds.bottom-margin)pan.y-=rect.bottom-(bounds.bottom-margin);
  transform();
}
