function chooseEffectPreset(effectId,presetId){const effect=board.effects.find(e=>e.id===effectId),preset=effectInfo(effect)?.presets?.find(p=>p.id===presetId);if(!effect||!preset)return false;if(effect.preset_id===preset.id)return true;commit(()=>{effect.preset_id=preset.id;effect.settings={...(preset.settings||{}),...(effect.settings||{})};});return true;}
