function populateFilters(){for(const [id,key,label] of [['status-filter','status','All statuses'],['tag-filter','tags','All action tags']]){const select=$(id),value=select.value,values=[...new Set(catalog.flatMap(r=>key==='tags'?(r.tags||[]):r[key]?[String(r[key])]:[]))].sort();select.innerHTML=`<option value="">${label}</option>`+values.map(v=>`<option value="${escapeHTML(v)}">${escapeHTML(v)}</option>`).join('');select.value=value;}const selected=$('version').value;$('version').innerHTML='<option value="">All versions</option>'+[...new Set(catalog.map(r=>String(r.version||'Imported')))].map(v=>`<option value="${escapeHTML(v)}">${escapeHTML(v)}</option>`).join('');$('version').value=selected;}
async function init(){try{const results=await Promise.allSettled([api('/api/project'),api('/api/catalog'),api('/api/board'),api('/api/effects')]);if(results[0].status==='fulfilled')project={...project,...results[0].value};if(results[1].status==='rejected')throw results[1].reason;catalog=results[1].value.items||[];if(results[2].status==='rejected')throw results[2].reason;const sceneIdMigration=results[2].value.nodes?.some(n=>!['start','end'].includes(n.kind)&&!n.scene_id);board=normalize(results[2].value);if(results[3]?.status==='fulfilled')effectRegistry=results[3].value.effects||[];$('project-title').textContent=project.title;document.title='Storyboard Studio · '+project.title;populateFilters();bind();await refreshBoards();const requested=new URL(location.href).searchParams.get('board');if(boardsAvailable&&requested&&requested!==board.board_id&&boards.some(b=>b.id===requested)){if(!showRecovery()){const result=await api('/api/boards/'+encodeURIComponent(requested)+'/activate',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});board=normalize(result.board);}}updateBoardIdentity();syncChosenPath();renderLibrary();const recovered=recoveryPending||showRecovery(),markerMigration=!recovered&&ensureDefaultMarkers();render();if(markerMigration||sceneIdMigration&&!recovered)changed();requestAnimationFrame(()=>requestAnimationFrame(fit));if(!markerMigration&&!sceneIdMigration)status(recovered?'Recovery needs review':'Saved locally');}catch(e){status('Load failed: '+e.message,true);$('empty-canvas').textContent='Could not load the local project. Reload after the server is available.';}}
init();
